def target(name):
    if name in alias and alias[name] in cp: return alias[name]
    if name in cp: return name
    return None
if __name__ == '__main__':
    freq=[l.split() for l in open('fa_freq.txt')]
    mods={'spin','pulse','fw','lg','xs','sm','2x','3x','4x','5x','solid','regular','brands','rotate-90','rotate-180','rotate-270','flip-horizontal','flip-vertical','stack','stack-1x','stack-2x','inverse','border','pull-left','pull-right','beat','fade','bounce','shake','li','ul','sharp','light','thin','duotone','chevron-','beat-fade','flip','spin-pulse','spin-reverse','10x','1x','6x','7x','8x','9x','xl','2xl','2xs','3xs'}
    tot=0; mapped=0; un=[]
    bad=[(k,v) for k,v in alias.items() if v not in cp]
    for c,n in freq:
        n=n[3:]; c=int(c)
        if n in mods: continue
        tot+=c
        if target(n): mapped+=c
        else: un.append((c,n))
    print('alias targets missing in lucide:', bad[:60])
    print(f'uses mapped {mapped}/{tot}; unmapped names {len(un)}')
    print(' '.join(f'{n}:{c}' for c,n in un))
